QX('x-p13', 'תרגול עצמי', 'תרגול עצמי 1: ״גבעת הזיתים״, רגע לפני תשלום בקופון קבוע',
   ['חברת ״גבעת הזיתים״ בע״מ הנפיקה אג״ח שערכה הנקוב 1,000 ש״ח, הנושאת ריבית נקובה של 5% לשנה, המשולמת בתום כל שנה. היום החברה משלמת קופון, ואחריו נותרו עוד 3 קופונים שנתיים, והערך הנקוב ייפרע עם האחרון שבהם. שיעור התשואה לפדיון הוא 4% לשנה.',
    '<b>נדרש:</b> מהו שווי האג״ח היום, מיד אחרי תשלום הקופון, ומהו שוויה היום, רגע לפני התשלום?'],
   'הזינו את הנתונים. B6: הקופון. B7: השווי מיד אחרי התשלום, בפונקציה PV. B8: השווי רגע לפני התשלום.',
   {'A1': 'ערך נקוב', 'B1': 1000, 'A2': 'ריבית נקובה', 'B2': 0.05, 'A3': 'קופונים שנותרו אחרי היום', 'B3': 3, 'A4': 'תשואה לפדיון', 'B4': 0.04,
    'A6': 'קופון שנתי', 'A7': 'מיד אחרי התשלום', 'A8': 'רגע לפני התשלום'},
   {'B6': '=B1*B2', 'B7': '=-PV(B4,B3,B6,B1)', 'B8': '=B7+B6'}, [220, 110], [], fmt={'B1': 'num0', 'B2': 'pct0', 'B4': 'pct0', 'B6': 'num0', 'B7': 'num2', 'B8': 'num2'},
   hints=['מיד אחרי התשלום נותרו 3 קופונים ופירעון: PV עם nper של 3.', 'רגע לפני: מוסיפים את הקופון של היום.'], remind='=-PV(rate, nper, pmt, fv)   =B7+B6', partial=['B6'],
   traps={'B8': [('=B7-B6', 'הפחתתם את הקופון. רגע לפני, הוא עוד מגיע למחזיק, ולכן מוסיפים אותו.'), ('=B7*(1+B4)', 'כאן אין תקופה בין שני הרגעים: אותו יום. מוסיפים את הקופון, ולא מכפילים.')]},
   note=[('tip', 'רגע לפני ומיד אחרי הם אותו יום. ההבדל ביניהם הוא בדיוק התשלום של היום.', 1)],
   done='מיד אחרי: 1,027.75 ש״ח. רגע לפני: 1,077.75 ש״ח.', xtitle='תרגול עצמי 1: רגע לפני תשלום')

